package br.com.cineo;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;import org.json.*;import java.util.*;import static br.com.cineo.MainActivity.*;
/** Owner controls backed by authenticated operations, with explicit restore confirmation. */
class OperationsHub {
 final MainActivity a;OperationsHub(MainActivity activity){a=activity;}JSONObject exportData;
 void get(String path,MainActivity.Done done){a.call("GET","/v8/ops"+path,null,done);}void post(String path,JSONObject data,MainActivity.Done done){a.call("POST","/v8/ops"+path,data,done);}void page(String id,String title){a.page(id,title,"",3,()->home());}
 void home(){a.page("operations-hub","Controle da plataforma","",3,()->a.moderationDesk.home());a.menu("bell","Avisos do aplicativo","Mensagens com período de exibição",()->notices());a.menu("chat","Pesquisas de satisfação","Perguntas e resultados reais",()->surveys());a.menu("refresh","Versões e recursos","Distribuição gradual e novidades",()->rollouts());a.menu("chart","Qualidade e armazenamento","Reprodução nos últimos 30 dias",()->quality());a.menu("shield","Backups de metadados","Exportação criptografada e teste de restauração",()->backups());a.menu("film","Catálogo e categorias","Organização editorial",()->catalogue());}
 void catalogue(){page("catalogue-management","Organizar catálogo");a.menu("film","Destaques e coleções","Curadoria do catálogo",()->a.pro.editorial());a.menu("layers","Categorias","Gêneros disponíveis",()->a.complete.categories());}
 void notices(){page("app-notices","Avisos do aplicativo");a.button(a.body,"Criar aviso",RED,()->noticeEditor(new JSONObject()));get("/notices",r->{JSONArray rows=r.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);a.title(a.body,row.optString("title"),18);a.text(a.body,row.optString("body")+"\n"+(row.optBoolean("active")?"Ativo":"Desativado")+" · até "+a.pro.date(row.optString("ends_at")),13,MUTED);a.button(a.body,"Editar aviso",CARD,()->noticeEditor(row));}});}
 void noticeEditor(JSONObject row){page("app-notice-editor","Preparar aviso");EditText title=a.field(a.body,"TÍTULO","Até 100 caracteres",false),body=a.field(a.body,"MENSAGEM","Texto do aviso",false),start=a.field(a.body,"INÍCIO · DATA E HORA ISO","2026-11-05T12:00:00Z",false),end=a.field(a.body,"TÉRMINO · DATA E HORA ISO","2026-11-12T12:00:00Z",false);title.setText(row.optString("title"));body.setText(row.optString("body"));body.setSingleLine(false);body.setMinLines(3);start.setText(row.optString("starts_at",java.time.Instant.now().toString()));end.setText(row.optString("ends_at",java.time.Instant.now().plusSeconds(604800).toString()));Spinner kind=a.select(a.body,"TIPO",new String[]{"info","maintenance","release"},row.optString("kind","info")),destination=a.select(a.body,"ABRIR AO TOCAR",new String[]{"support","updates","inbox","preferences","library"},row.optString("destination","support"));CheckBox active=check("Exibir aviso",row.optBoolean("active",true));a.button(a.body,"Salvar aviso",RED,()->a.safe(()->{JSONObject data=a.obj("title",title.getText().toString(),"body",body.getText().toString(),"starts_at",start.getText().toString(),"ends_at",end.getText().toString(),"kind",kind.getSelectedItem(),"destination",destination.getSelectedItem(),"active",active.isChecked());if(row.has("id"))data.put("id",row.getString("id"));post("/notices",data,r->notices());}));}
 CheckBox check(String text,boolean value){CheckBox box=new CheckBox(a);box.setText(text);box.setTextColor(WHITE);box.setChecked(value);a.body.addView(box);return box;}
 void surveys(){page("survey-management","Pesquisas de satisfação");a.button(a.body,"Criar pesquisa",RED,()->surveyEditor(new JSONObject()));get("/surveys",r->{JSONArray rows=r.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);a.title(a.body,row.optString("question"),18);JSONArray options=row.getJSONArray("options"),counts=row.getJSONArray("counts");for(int n=0;n<options.length();n++)a.text(a.body,options.optString(n)+" · "+counts.optInt(n)+" voto(s)",14,MUTED);a.button(a.body,"Editar / encerrar",CARD,()->surveyEditor(row));}});}
 void surveyEditor(JSONObject row){page("survey-editor","Preparar pesquisa");EditText question=a.field(a.body,"PERGUNTA","O que devemos melhorar?",false),options=a.field(a.body,"OPÇÕES · UMA POR LINHA","De duas a seis respostas",false);question.setText(row.optString("question"));options.setSingleLine(false);options.setMinLines(5);JSONArray old=row.optJSONArray("options");if(old!=null){ArrayList<String> values=new ArrayList<>();for(int i=0;i<old.length();i++)values.add(old.optString(i));options.setText(android.text.TextUtils.join("\n",values));}CheckBox active=check("Aceitar respostas",row.optBoolean("active",true));a.text(a.body,"Após receber votos, as opções ficam protegidas contra alteração.",13,MUTED);a.button(a.body,"Salvar pesquisa",RED,()->a.safe(()->{JSONArray values=new JSONArray();for(String line:options.getText().toString().split("\n"))if(!line.trim().isEmpty())values.put(line.trim());JSONObject data=a.obj("question",question.getText().toString(),"options",values,"active",active.isChecked());if(row.has("id"))data.put("id",row.getString("id"));post("/surveys",data,r->surveys());}));}
 void rollouts(){page("release-controls","Versões e recursos");get("/rollouts",r->{JSONArray flags=r.getJSONArray("flags");for(int i=0;i<flags.length();i++){JSONObject flag=flags.getJSONObject(i);a.title(a.body,flag.optString("description",flag.optString("name")),18);a.button(a.body,"Disponível para "+flag.optInt("percentage")+"% · ajustar",CARD,()->percentage(flag,true));}JSONArray rows=r.getJSONArray("versions");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);a.title(a.body,"Versão "+row.optString("version_name"),20);a.text(a.body,row.optString("title")+" · "+row.optInt("rollout")+"%",14,MUTED);a.button(a.body,"Ajustar distribuição",CARD,()->percentage(row,false));a.button(a.body,"Editar novidades e atalhos",CARD,()->newsEditor(row));}});}
 void percentage(JSONObject row,boolean flag){EditText input=new EditText(a);input.setInputType(2);input.setText(String.valueOf(row.optInt(flag?"percentage":"rollout")));new AlertDialog.Builder(a).setTitle("Percentual de disponibilidade").setMessage("Use 0 para suspender a oferta; 100 libera para todas as contas. Versões já instaladas não são desinstaladas.").setView(input).setNegativeButton("Cancelar",null).setPositiveButton("Aplicar",(d,n)->a.safe(()->{JSONObject data=a.obj("percentage",Integer.parseInt(input.getText().toString()));if(flag)data.put("flag",row.getString("name"));else data.put("version",row.getInt("version")).put("active",true);post("/rollouts",data,r->rollouts());})).show();}
 void newsEditor(JSONObject row){page("release-news-editor","Novidades da versão");EditText title=a.field(a.body,"TÍTULO","Novidades desta atualização",false),items=a.field(a.body,"ITENS · JSON","Lista de título, texto e ferramenta",false);title.setText(row.optString("title"));items.setSingleLine(false);items.setMinLines(8);JSONArray current=row.optJSONArray("items");items.setText(current==null?"[]":current.toString());a.text(a.body,"Formato: [{\"title\":\"Novo perfil\",\"body\":\"Ferramentas organizadas\",\"tool\":\"preferences\"}]",12,MUTED);a.button(a.body,"Salvar novidades",RED,()->a.safe(()->post("/news",a.obj("version",row.getInt("version"),"title",title.getText().toString(),"items",new JSONArray(items.getText().toString())),r->rollouts())));}
 void quality(){page("playback-quality","Qualidade de reprodução");get("/quality",r->{a.title(a.body,r.optInt("samples")+" sessões registradas",24);a.text(a.body,"Início médio: "+r.optInt("startup_average_ms")+" ms\nInterrupções por carregamento: "+r.optInt("stalls")+"\nTempo em carregamento: "+r.optLong("stall_ms")/1000+" s",16,MUTED);Object storage=r.opt("storage");a.title(a.body,"Armazenamento",20);a.text(a.body,storage==null?"Sem dados disponíveis":storage.toString(),14,MUTED);a.text(a.body,"A amostra registra tempos técnicos. Não inclui conteúdo de comentários nem senhas.",13,MUTED);});}
 void backups(){page("metadata-backups","Backups de metadados");a.button(a.body,"Criar backup criptografado",RED,()->post("/backups",new JSONObject(),r->backups()));get("/backups",r->{a.text(a.body,r.optString("scope"),13,MUTED);JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.empty(a.body,"shield","Nenhum backup criado","Crie uma cópia para testar a recuperação dos metadados.");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);a.title(a.body,a.pro.date(row.optString("created_at")),18);JSONObject summary=row.optJSONObject("summary");a.text(a.body,(summary==null?"":summary.optLong("bytes")/1024+" KB · "+summary.optString("source"))+"\nSHA-256: "+row.optString("sha256"),12,MUTED);a.button(a.body,"Testar restauração",CARD,()->post("/backup/"+row.optString("id")+"/probe",new JSONObject(),probe->restorePreview(row,probe)));a.button(a.body,"Exportar arquivo e chave",CARD,()->post("/backup/"+row.optString("id")+"/export",new JSONObject(),data->{exportData=data;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("application/json");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"Cineo-recuperacao-"+row.optString("id")+".json");a.startActivityForResult(intent,46);}));a.button(a.body,"Remover esta cópia",BG,()->new AlertDialog.Builder(a).setTitle("Remover backup?").setMessage("Guarde a exportação antes de remover a cópia do servidor.").setNegativeButton("Manter",null).setPositiveButton("Remover",(d,n)->a.safe(()->post("/backup/"+row.optString("id")+"/remove",a.obj("confirm",true),ok->backups()))).show());}});}
 void restorePreview(JSONObject backup,JSONObject probe){page("backup-probe","Teste de restauração");a.title(a.body,"Verificação concluída",22);a.text(a.body,probe.toString( ).replace(",",",\n"),13,MUTED);a.text(a.body,"A restauração adiciona somente registros ausentes. Os registros atuais são preservados. Arquivos de vídeo e contas de acesso não fazem parte desta cópia.",14,MUTED);EditText confirm=a.field(a.body,"CONFIRMAÇÃO","Digite RESTAURAR AUSENTES",false);a.button(a.body,"Restaurar registros ausentes",RED,()->new AlertDialog.Builder(a).setTitle("Aplicar recuperação?").setMessage("Revise o resultado do teste antes de continuar.").setNegativeButton("Cancelar",null).setPositiveButton("Restaurar",(d,n)->a.safe(()->post("/backup/"+backup.optString("id")+"/restore",a.obj("confirm",confirm.getText().toString()),r->{a.notice("Recuperação concluída.",false);a.text(a.body,r.toString(),13,GREEN);}))).show());}
 String sha(byte[] raw)throws Exception{StringBuilder out=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(raw))out.append(String.format(java.util.Locale.US,"%02x",b&255));return out.toString();}
 boolean result(int request,int result,Intent data){if(request!=46)return false;if(result!=Activity.RESULT_OK||data==null||data.getData()==null||exportData==null)return true;Uri destination=data.getData();JSONObject exported=exportData;exportData=null;a.io.execute(()->{try{java.net.HttpURLConnection connection=(java.net.HttpURLConnection)new java.net.URL(exported.getString("url")).openConnection();connection.setConnectTimeout(20000);connection.setReadTimeout(60000);connection.setInstanceFollowRedirects(false);try{if(connection.getResponseCode()!=200)throw new java.io.IOException("Não foi possível baixar o backup.");java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();try(java.io.InputStream input=connection.getInputStream()){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){bytes.write(buffer,0,n);if(bytes.size()>10485760)throw new java.io.IOException("Arquivo excede o limite.");}}byte[] raw=bytes.toByteArray();String hash=sha(raw);if(!hash.equals(exported.getString("sha256")))throw new java.io.IOException("O arquivo baixado está incompleto.");JSONObject file=a.obj("format","cineo-recovery","sha256",hash,"recovery_key",exported.getString("recovery_key"),"backup",new JSONObject(new String(raw,java.nio.charset.StandardCharsets.UTF_8)));try(java.io.OutputStream output=a.getContentResolver().openOutputStream(destination)){output.write(file.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}finally{connection.disconnect();}a.runOnUiThread(()->Toast.makeText(a,"Backup exportado. Guarde o arquivo em local seguro.",Toast.LENGTH_LONG).show());}catch(Exception e){a.runOnUiThread(()->Toast.makeText(a,"Falha ao exportar: "+e.getMessage(),Toast.LENGTH_LONG).show());}});return true;}
}
